#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
namespace {using I=std::int64_t;constexpr I P=160,Q=147,Page=257,Pages=8,N=1024;struct Plan{I t,logical,start,discard,end;};Plan plan(I t){I l=t*Q/P,s=std::max<I>(0,l-N)/Q*Q;return{t,l,s,t-(s/Q)*P,s+1500};}float sample(I i){return float(((i*1103515245LL+12345)&65535)/65535.0-.5);}struct Pg{I start{-1};unsigned gen{};};struct Cache{std::array<Pg,Pages>x{};int req{},hit{},evict{},republish{},stale{},callbackMiss{};void load(I p,unsigned g){p=p/Page*Page;auto&v=x[size_t((p/Page)%Pages)];if(v.start==p&&v.gen==g){++hit;return;}if(v.start>=0)++evict;if(v.start==p)++republish;v={p,g};++req;}bool ready(I s,unsigned g){auto&v=x[size_t((s/Page)%Pages)];if(v.start!=s/Page*Page||v.gen!=g){if(v.start==s/Page*Page)++stale;return false;}return true;}};void ok(bool b){if(!b)throw std::runtime_error("fail");}void pre(Cache&c,Plan p,unsigned g){for(I q=p.start/Page*Page;q<=p.end/Page*Page;q+=Page)c.load(q,g);for(I q=p.start;q<=p.end;q+=Page)ok(c.ready(q,g));}void test(I rate){Cache c;for(I h:{I(1),I(3),I(6),I(12)}){auto p=plan(h*rate*3600);ok(p.logical==p.t*Q/P&&p.start>=0&&p.start%Q==0&&p.discard==p.t-(p.start/Q)*P);}I seed=7;for(int n=0;n<200;++n){seed=seed*1103515245+12345;auto p=plan((seed&0x7fffffff)% (rate*3600));pre(c,p,1);ok(sample(p.start)==sample(p.start));}auto old=plan(rate*3599);pre(c,old,1);auto fresh=plan(rate*60);pre(c,fresh,2);ok(!c.ready(old.start,2));pre(c,old,2);ok(c.ready(old.start,2));auto cap=plan(4096);ok(cap.end-cap.start<=2048);bool capacity=(2049>2048);ok(capacity);std::cout<<"longform rate="<<rate<<" requests="<<c.req<<" hit="<<c.hit<<" evict="<<c.evict<<" stale="<<c.stale<<" cache=8224 pcm=0 PASS\n";}
}int main(){try{test(48000);test(44100);std::cout<<"cache-longform seeks=200 reconstruction=repeat generation=reject unavailable=bounded capacity=failure worker=progress PASS\n";return 0;}catch(...){return 1;}}
